sys_script_client.script:
function onSubmit() {

    g_form.clearMessages();

    var numberFields = {
        max: 'Max',
        obtained: 'Obtained'
    };
    var firstInvalidField = '';

    for (var field in numberFields) {
        var value = g_form.getValue(field);

        if (value !== '' && parseFloat(value) < 0) {
            g_form.addErrorMessage(numberFields[field] + ' cannot be negative.');
            firstInvalidField = firstInvalidField || field;
        }
    }

    var max = g_form.getValue('max');
    var obtained = g_form.getValue('obtained');

    if (max !== '' && obtained !== '' && parseFloat(obtained) > parseFloat(max)) {
        g_form.addErrorMessage('Obtained cannot be greater than Max.');
        firstInvalidField = firstInvalidField || 'obtained';
    }

    if (firstInvalidField) {
        g_form.getControl(firstInvalidField).focus();
        return false;
    }
}
